CREATE OR REPLACE FUNCTION public.require_period_operation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE old_books jsonb; new_books jsonb; BEGIN
 IF current_setting('ledgerline.erasing',true)='on' THEN RETURN coalesce(NEW,OLD); END IF;
 IF TG_OP='DELETE' THEN IF jsonb_array_length(coalesce(OLD.data->'books'->'closedPeriods','[]'))>0 OR EXISTS(SELECT 1 FROM public.period_close_evidence WHERE owner_id=OLD.owner_id) THEN RAISE EXCEPTION 'Use confirmed account deletion to remove closing history'; END IF; RETURN OLD; END IF;
 IF EXISTS(SELECT 1 FROM public.period_operation_authority WHERE owner_id=NEW.owner_id AND transaction_id=txid_current()) THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN SELECT coalesce(data->'books','{}') INTO old_books FROM public.finance_preferences WHERE owner_id=NEW.owner_id FOR UPDATE; old_books:=coalesce(old_books,'{}'); ELSE old_books:=coalesce(OLD.data->'books','{}'); END IF;
 new_books:=coalesce(NEW.data->'books','{}');
 IF coalesce(old_books->'closedPeriods','[]') IS DISTINCT FROM coalesce(new_books->'closedPeriods','[]') OR coalesce(old_books->'periodLog','[]') IS DISTINCT FROM coalesce(new_books->'periodLog','[]') THEN RAISE EXCEPTION 'Close or reopen on Audit so evidence is retained'; END IF; RETURN NEW; END $$;